export const CURATED_ROBOT_DESIGN_INTENT =
  "Verified robot Manhattan v2: street-lattice robot head with antenna cap, side ears, two square eyes, mouth bar, and neck strokes.";

export function curatedRobotRouteKm(): number {
  let meters = 0;
  const coords = CURATED_ROBOT_MANHATTAN_COORDS;
  for (let i = 1; i < coords.length; i++) {
    meters += haversineMeters(coords[i - 1]!, coords[i]!);
  }
  return meters / 1000;
}

export function curatedRobotManhattanMapNativeCandidate(): MapNativeCandidate {
  const anchors = CURATED_ROBOT_MANHATTAN_COORDS;
  let minLat = Infinity;
  let maxLat = -Infinity;
  let minLng = Infinity;
  let maxLng = -Infinity;
  for (const [lat, lng] of anchors) {
    minLat = Math.min(minLat, lat);
    maxLat = Math.max(maxLat, lat);
    minLng = Math.min(minLng, lng);
    maxLng = Math.max(maxLng, lng);
  }
  return {
    placement: {
      center: [(minLat + maxLat) / 2, (minLng + maxLng) / 2],
      rotationDeg: 29,
      scale: 1,
    },
    anchors,
    km: curatedRobotRouteKm(),
    designIntent: CURATED_ROBOT_DESIGN_INTENT,
    kind: "street-design",
    routeMode: "direct-grid",
  };
}

export function curatedRobotRouteLine(): RouteLineString {
  const coords = CURATED_ROBOT_MANHATTAN_COORDS;
  return {
    coordinates: coords,
    distanceMeters: curatedRobotRouteKm() * 1000,
    blockWaypoints: coords,
  };
}
